module benchmark/solution

import std/string (chars)

pure func romanPairs() -> [(int, string)] =
  [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
   (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]

pure func encode(n: int, pairs: [(int, string)]) -> string =
  match pairs {
    [] => "",
    p :: rest => match p {
      (v, s) => if n >= v then "${s}${encode(n - v, pairs)}" else encode(n, rest)
    }
  }

export pure func toRoman(n: int) -> string = encode(n, romanPairs())

pure func charValue(c: string) -> int =
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }

pure func decode(vals: [int]) -> int =
  match vals {
    [] => 0,
    a :: rest => match rest {
      [] => a,
      b :: _ => if a < b then decode(rest) - a else a + decode(rest)
    }
  }

export pure func fromRoman(s: string) -> int =
  decode(map(charValue, chars(s)))

pure func map(f: string -> int, xs: [string]) -> [int] =
  match xs {
    [] => [],
    x :: rest => f(x) :: map(f, rest)
  }

export pure func roundtrip(n: int) -> bool = fromRoman(toRoman(n)) == n

export pure func distinctEncoding(a: int, b: int) -> bool =
  if a == b then true else toRoman(a) != toRoman(b)

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

